+// RF-004: el descuento (0 a 100 %, hasta 2 decimales) se aplica a la línea y su total se redondea al centavo.
+// Se calcula en centésimas de punto porcentual con BigInt para no arrastrar errores binarios (ADR-001).
+function totalLineaCentavos({ cantidad, precioUnitarioCentavos, descuentoPorcentaje = 0 }) {
+  const centesimas = Math.round(descuentoPorcentaje * 100);
+  if (
+    typeof descuentoPorcentaje !== "number" ||
+    !(descuentoPorcentaje >= 0 && descuentoPorcentaje <= 100) ||
+    Math.abs(descuentoPorcentaje * 100 - centesimas) > 1e-6
+  )
+    throw new RangeError("Descuento inválido: debe ser un porcentaje de 0 a 100 con hasta 2 decimales");
+  const base = 10000n;
+  const numerador = BigInt(cantidad) * BigInt(precioUnitarioCentavos) * (base - BigInt(centesimas));
+  return Number((numerador + base / 2n) / base);
+}
